   'courseai_image_count_many',\n    'courseai_review_title',\n    'courseai_review_subtitle',\n    'courseai_review_step_label',\n    'courseai_review_fullname_label',\n    'courseai_review_fullname_placeholder',\n    'courseai_review_shortname_label',\n    'courseai_review_shortname_placeholder',\n    'courseai_review_shortname_note',\n    'courseai_review_category_label',\n    'courseai_review_category_loading',\n    'courseai_review_cancel',\n    'courseai_review_confirm',\n    'courseai_proposals_title',\n    'courseai_proposals_clarification_label',\n    'courseai_proposals_other_label',\n    'courseai_proposals_other_placeholder',\n    'courseai_btn_execute_proposal',\n    'courseai_btn_discard_proposals',\n    'courseai_proposals_fallen_label',\n    'courseai_proposals_destructive_badge',\n    'courseai_btn_add_section',\n    'courseai_btn_add_activity',\n    'courseai_btn_add_subsection',\n    'courseai_btn_add',\n    'courseai_menu_activity_or_resource',\n    'courseai_add_section_placeholder',\n    'courseai_add_activity_placeholder',\n    'courseai_add_subsection_placeholder',\n    'courseai_drag_handle_label',\n    'courseai_resize_panels',\n    'courseai_log_label',\n    'courseai_log_user_request',\n    'courseai_log_deleted_section',\n    'courseai_log_deleted_activity',\n    'courseai_log_regenerated_section',\n    'courseai_log_regenerated_activity',\n    'courseai_log_added_section',\n    'courseai_log_added_activity',\n    'courseai_log_image_discarded',\n    'courseai_log_image_regenerated',\n    'courseai_log_proposal_applied',\n    'courseai_log_proposals_dismissed',\n    'courseai_log_ai_thinking',\n    'courseai_log_ai_working',\n    'courseai_log_ai_course_configuration',\n    'courseai_log_ai_review_ready',\n    'courseai_log_ai_proposals_ready',\n    'courseai_log_ai_completed',\n    'courseai_log_user_approved',\n    'courseai_log_reordered_sections',\n    'courseai_log_moved_section',\n    'courseai_log_added_section_named',\n    'courseai_log_added_activity_named',\n    'courseai_log_add_activity_target',\n    'courseai_log_add_section_target',\n    'proposal_add_activity',\n    'proposal_add_section',\n    'proposal_add_subsection',\n    'courseai_log_reordered_activities',\n    'courseai_log_reordered_activities_generic',\n    'courseai_log_moved_activity',\n    'courseai_log_ai_review_updated',\n    'courseai_show_more',\n    'courseai_show_less',\n    'courseai_show_full_message',\n    'courseai_log_ai_planned_structure',\n    'courseai_checklist_section_count',\n    'courseai_decision_title',\n    'courseai_decision_accept',\n    'courseai_decision_adjust',\n    // Server-side thread log string_ids (match the service Message names). Prefetched\n    // so replayThread localizes the full transcript on reload without N round-trips.\n    'ai_planned_structure',\n    'ai_course_configuration',\n    'log_user_approved',\n    'log_user_adjusted',\n    'log_proposal_applied',\n    'log_proposal_custom',\n    'log_proposals_dismissed',\n    'log_user_stopped',\n    'log_user_resumed',\n    'log_add_section',\n    'log_add_subsection',\n    'log_delete_section',\n    'log_delete_section_named',\n    'log_reorder_sections',\n    'log_moved_section',\n    'log_replan_section',\n    'log_add_activity',\n    'log_delete_activity',\n    'log_delete_activity_named',\n    'log_reorder_activities',\n    'log_moved_activity',\n    'log_move_activity_to',\n    'proposal_move_activity',\n    'log_replan_activity',\n    'log_discard_image',\n    'log_replan_image',\n    'course_completed',\n    'course_failed',\n    'review_plan_detailed',\n];\n\n/**\n * Load all courseai strings from lang pack.\n *\n * @returns {Promise<Object>}\n */\nexport const loadCourseaiStrings = async() => {\n    const values = await get_strings(STRING_KEYS.map((key) => ({key, component: 'local_coursegen'})));\n    return Object.fromEntries(STRING_KEYS.map((key, i) => [key, values[i]]));\n};\n\n/**\n * Localize a backend message into the user's language.\n *\n * The backend streams every human-readable message as\n * `{string_id, string, string_args}`. We localize by `string_id` against the\n * plugin's lang pack (the catalog is mirrored 1:1), passing `string_args` as\n * the Moodle `$a` object. When the key is missing locally (e.g. a brand-new\n * backend string not yet shipped in this lang pack), we fall back to the\n * server-rendered `string`.\n *\n * @param {Object} message - { string_id, string, string_args? }\n * @returns {Promise<string>}\n */\nexport const localizeMessage = async(message) => {\n    if (!message || !message.string_id) {\n        return (message && message.string) || '';\n    }\n    try {\n        const text = await get_string(message.string_id, 'local_coursegen', message.string_args || null);\n        // Moodle renders \"[[key]]\" for an unknown string id: prefer the server text.\n        if (typeof text === 'string' && text.startsWith('[[')) {\n            return message.string || text;\n        }\n        return text;\n    } catch (e) {\n        return message.string || '';\n    }\n};\n"],"names":["STRING_KEYS","async","values","map","key","component","Object","fromEntries","i","message","string_id","string","text","string_args","startsWith","e"],"mappings":";;;;;;;;MAyBMA,YAAc,CAChB,wBACA,2BACA,wBACA,yBACA,2BACA,yBACA,4BACA,8BACA,4BACA,gCACA,+BACA,iCACA,wBACA,8BACA,0BACA,gCACA,mCACA,yCACA,+BACA,iCACA,sBACA,0BACA,wBACA,wBACA,4BACA,6BACA,6BACA,iCACA,4BACA,sCACA,uCACA,yCACA,qCACA,uCACA,sCACA,+BACA,4BACA,sBACA,wBACA,oBACA,0BACA,0BACA,wBACA,yBACA,6BACA,sBACA,qBACA,uBACA,8BACA,sBACA,uBACA,wCACA,uCACA,yCACA,wCACA,2BACA,4BACA,2BACA,+BACA,uBACA,+BACA,6BACA,sBACA,4BACA,0BACA,0BACA,6BACA,2BACA,uBACA,4BACA,wBACA,uBACA,iCACA,6BACA,gCACA,+BACA,kCACA,+BACA,qCACA,oCACA,uCACA,wCACA,2CACA,8BACA,kCACA,6BACA,yBACA,uCACA,qCACA,4BACA,6BACA,4BACA,4BACA,+BACA,8BACA,iCACA,+BACA,iCACA,yBACA,6BACA,uCACA,2BACA,oCACA,4BACA,sCACA,wCACA,0CACA,sCACA,yCACA,2BACA,8BACA,4BACA,yBACA,yBACA,2BACA,0BACA,2BACA,